const body = $json.body ?? {};
const headers = $json.headers ?? {};

const action = String(body.action ?? '')
  .trim()
  .toLowerCase();

const email_normalizado = body.email
  ? String(body.email).trim().toLowerCase()
  : null;

const password =
  typeof body.password === 'string'
    ? body.password
    : null;

// Permitir token tanto en body como en Authorization: Bearer ...
let session_token = body.session_token
  ? String(body.session_token).trim()
  : null;

const authorization =
  headers.authorization ??
  headers.Authorization ??
  '';

if (!session_token && typeof authorization === 'string') {
  const match = authorization.match(/^Bearer\s+(.+)$/i);

  if (match) {
    session_token = match[1].trim();
  }
}

const accionesPermitidas = [
  'login',
  'logout',
  'validate',
];

let error = null;

if (!accionesPermitidas.includes(action)) {
  error = 'Acción no válida';
}

if (!error && action === 'login') {
  if (!email_normalizado) {
    error = 'El email es obligatorio';
  } else if (!password) {
    error = 'La contraseña es obligatoria';
  }
}

if (!error && ['logout', 'validate'].includes(action)) {
  if (!session_token) {
    error = 'El token de sesión es obligatorio';
  }
}

return [
  {
    json: {
      route: error ? 'invalid' : action,
      action,
      email_normalizado,
      password,
      session_token,
      error,
    },
  },
];

const crypto = require('crypto');

const usuario = $json;
const entrada = $('Normalizar y validar entrada').first().json;

let password_ok = false;

try {
  const hashCalculado = crypto.pbkdf2Sync(
    entrada.password,
    usuario.password_salt,
    100000,
    32,
    'sha256'
  );

  const hashGuardado = Buffer.from(
    usuario.password_hash,
    'hex'
  );

  password_ok =
    hashGuardado.length === hashCalculado.length &&
    crypto.timingSafeEqual(hashGuardado, hashCalculado);

} catch (error) {
  password_ok = false;
}

return [
  {
    json: {
      usuario_id: usuario.usuario_id,
      nombre: usuario.nombre,
      email_normalizado: usuario.email_normalizado,
      estado: usuario.estado,
      password_ok
    }
  }
];

