  expira.getTime() <= ahora.getTime();

return [
  {
    json: {
      session_id: sesion.session_id,
      usuario_id: sesion.usuario_id,
      session_token: sesion.session_token,
      creada_en: sesion.creada_en,
      expira_en: sesion.expira_en,
      estado: yaExpirada ? 'EXPIRADA' : 'CERRADA',
      cerrada_en: yaExpirada ? (sesion.cerrada_en ?? '') : ahora.toISOString(),
      ultima_validacion: ahora.toISOString(),
      ya_expirada: yaExpirada
    }
  }
];

